import React from "react";
import { Space as ArcoSpace, SpaceProps } from "@arco-design/web-react";
import { useFormLayout } from "../FormLayout";
import toArray from "rc-util/es/Children/toArray";

export const Space: React.FC<React.PropsWithChildren<SpaceProps>> = (props) => {
  const layout = useFormLayout();

  /**
   * formily 内部组件会通过 createElement 包装一层，导致 children 包装一个 <Fragment />
   * 导致传入 ArcoSpace 的只有一个节点生成一个 SpaceItem
   */
  const childNodes = toArray(props.children, { keepEmpty: true });

  return React.createElement(ArcoSpace, {
    size: props.size ?? layout?.spaceSize,
    ...props,
    children: childNodes,
  });
};

export default Space;
